    # Find the rectangular nonzero canvas, ignoring isolated outside markers.
    # Its rows are the long contiguous nonzero run.
    candidates = []
    for r in range(R):
        cols = [c for c, v in enumerate(grid[r]) if v != 0]
        if cols:
            candidates.append((r, min(cols), max(cols)))
    # The canvas is the largest contiguous block of rows containing a wide field.
    runs = []
    current = []
    for item in candidates:
        if current and item[0] != current[-1][0] + 1:
            runs.append(current)
            current = []
        current.append(item)
    if current:
        runs.append(current)
    run = max(runs, key=len)
    r0, r1 = run[0][0], run[-1][0]
    # Ignore isolated markers by finding columns occupied across most canvas rows.
    c0 = min(c for r, c, _ in run)
    c1 = max(c for r, _, c in run)
    board = [grid[r][c0:c1+1] for r in range(r0, r1+1)]

    # The outside markers encode a reflection and a color exchange.
    outside = [(r, c, grid[r][c]) for r in range(R) for c in range(C)
               if grid[r][c] and not (r0 <= r <= r1 and c0 <= c <= c1)]
    colors = {v for r, c, v in outside}
    if 2 in colors and 8 in colors:
